head.b:skin:
/*
  -----------------------------------------------
  Blogger Theme Style & Designer Variables
  -----------------------------------------------
  <Group description="Theme Colors" selector="body">
    <Variable name="body.bg.color" description="Background Color" type="color" default="#f1f5f9" value="#f1f5f9"/>
    <Variable name="body.text.color" description="Text Color" type="color" default="#1f2937" value="#1f2937"/>
    <Variable name="primary.brand.color" description="Brand Color" type="color" default="#2563eb" value="#2563eb"/>
  </Group>
*/

/* Blogger Required Reset */
body {
  margin: 0;
  padding: 0;
  background-color: $(body.bg.color);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: $(body.text.color);
  line-height: 1.5;
}

* { box-sizing: border-box; }

:root {
  --primary-color: #0f172a;
  --accent-color: #2563eb;
  --bg-slate: #f8fafc;
  --border-color: #e2e8f0;
  --sidebar-width: 520px;
}

body {
  background-color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.blogger-hidden-section { display: none !important; }

/* Header */
.app-header {
  background: #0f172a;
  color: #ffffff;
  padding: 0.75rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  position: sticky;
  top: 0;
  z-index: 50;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.app-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-weight: 700;
  font-size: 1.25rem;
  color: #ffffff;
  text-decoration: none;
}

.app-brand i { color: #38bdf8; font-size: 1.5rem; }

.domain-badge {
  font-size: 0.75rem;
  background: rgba(56, 189, 248, 0.2);
  color: #38bdf8;
  padding: 2px 8px;
  border-radius: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.legal-nav {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.8rem;
}

.legal-nav a {
  color: #94a3b8;
  text-decoration: none;
  transition: color 0.2s ease;
}

.legal-nav a:hover { color: #38bdf8; text-decoration: underline; }

.header-actions { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.85rem;
  font-size: 0.85rem;
  font-weight: 500;
  border-radius: 0.375rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn-primary { background-color: #2563eb; color: #ffffff; }
.btn-primary:hover { background-color: #1d4ed8; }

.btn-success { background-color: #10b981; color: #ffffff; }
.btn-success:hover { background-color: #059669; }

.btn-secondary { background-color: #475569; color: #ffffff; }
.btn-secondary:hover { background-color: #334155; }

.btn-outline { background-color: transparent; border-color: #cbd5e1; color: #334155; }
.btn-outline:hover { background-color: #f1f5f9; border-color: #94a3b8; }

.btn-outline-dark { background-color: transparent; border-color: #334155; color: #e2e8f0; }
.btn-outline-dark:hover { background-color: #1e293b; color: #ffffff; }

.btn-danger { background-color: #ef4444; color: #ffffff; }
.btn-danger:hover { background-color: #dc2626; }

.btn-sm { padding: 0.25rem 0.5rem; font-size: 0.75rem; }

/* Container */
.app-container {
  display: flex;
  flex: 1;
  height: calc(100vh - 57px);
  overflow: hidden;
}

.editor-panel {
  width: var(--sidebar-width);
  min-width: 360px;
  max-width: 600px;
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
  display: flex;
  flex-direction: column;
  height: 100%;
  z-index: 20;
}

.editor-tabs {
  display: flex;
  overflow-x: auto;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  scrollbar-width: thin;
}

.editor-tab-btn {
  padding: 0.75rem 0.9rem;
  font-size: 0.825rem;
  font-weight: 600;
  color: #64748b;
  border: none;
  background: transparent;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  white-space: nowrap;
  transition: all 0.2s;
}

.editor-tab-btn:hover { color: #2563eb; background: #f1f5f9; }
.editor-tab-btn.active { color: #2563eb; border-bottom-color: #2563eb; background: #ffffff; }

.editor-content { flex: 1; overflow-y: auto; padding: 1.25rem; }
.tab-pane { display: none; }
.tab-pane.active { display: block; }

.section-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 0.5rem;
}

.form-group { margin-bottom: 1rem; }
.form-row { display: flex; gap: 0.75rem; }
.form-row .form-group { flex: 1; }

label { display: block; font-size: 0.8rem; font-weight: 600; color: #334155; margin-bottom: 0.35rem; }

input[type="text"], input[type="email"], input[type="tel"], input[type="url"], input[type="date"], input[type="month"], select, textarea {
  width: 100%;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.375rem;
  background-color: #ffffff;
  color: #0f172a;
}

input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

textarea { resize: vertical; min-height: 80px; }

.checkbox-group { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.5rem; }
.checkbox-group label { margin-bottom: 0; font-weight: 400; cursor: pointer; }

.entry-card {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

.entry-card-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.75rem; }
.entry-card-title { font-weight: 600; font-size: 0.9rem; color: #334155; }
.entry-actions { display: flex; gap: 0.25rem; }

.color-swatches { display: flex; gap: 0.4rem; align-items: center; margin-top: 0.35rem; }
.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 1px #cbd5e1;
  transition: transform 0.15s ease;
}
.swatch:hover { transform: scale(1.15); }

/* Right Preview Panel */
.preview-panel {
  flex: 1;
  background: #334155;
  overflow-y: auto;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.preview-toolbar {
  background: #ffffff;
  padding: 0.6rem 1.25rem;
  border-radius: 0.5rem;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.25rem;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.15);
  flex-wrap: wrap;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: #334155;
}

.toolbar-group select, .toolbar-group input[type="color"] {
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  border: 1px solid #cbd5e1;
  height: 32px;
}

.toolbar-group input[type="color"] { width: 36px; padding: 2px; cursor: pointer; }

.resume-paper {
  background: #ffffff;
  width: 210mm;
  min-height: 297mm;
  box-shadow: 0 10px 25px -5px rgba(0,0,0,0.3);
  position: relative;
  margin: 0 auto;
  box-sizing: border-box;
}

.mobile-view-toggle {
  display: none;
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 100;
  border-radius: 50px;
  padding: 0.75rem 1.25rem;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.3);
}

@media (max-width: 992px) {
  .app-container { flex-direction: column; height: auto; overflow: visible; }
  .editor-panel { width: 100%; max-width: 100%; height: auto; }
  .preview-panel { width: 100%; padding: 1rem 0.5rem; }
  .resume-paper { width: 100%; max-width: 210mm; min-height: auto; }
  .mobile-view-toggle { display: inline-flex; }
}

/* RESUME TEMPLATES STYLING */
.template-modern { display: flex; min-height: 297mm; }
.template-modern .sidebar { width: 32%; background-color: var(--accent-color, #2563eb); color: #ffffff; padding: 2rem 1.25rem; }
.template-modern .main-content { width: 68%; padding: 2rem 1.5rem; }
.template-modern .profile-img { width: 120px; height: 120px; border-radius: 50%; object-fit: cover; margin: 0 auto 1.25rem auto; display: block; border: 3px solid rgba(255,255,255,0.3); }

.template-classic { padding: 2.5rem; }
.template-classic .header-classic { text-align: center; border-bottom: 2px solid var(--accent-color, #1e293b); padding-bottom: 1.25rem; margin-bottom: 1.5rem; }
.template-classic .name-classic { font-size: 2.2rem; font-weight: 700; color: var(--accent-color, #1e293b); text-transform: uppercase; letter-spacing: 0.05em; }

.template-minimal { padding: 2.5rem; }
.template-minimal .header-minimal { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 2rem; border-bottom: 1px solid #e2e8f0; padding-bottom: 1.5rem; }

.template-creative .banner { background: var(--accent-color, #2563eb); color: #ffffff; padding: 2.5rem 2rem; display: flex; align-items: center; gap: 1.5rem; }
.template-creative .banner-img { width: 110px; height: 110px; border-radius: 12px; object-fit: cover; border: 3px solid #ffffff; }

.template-compact { padding: 1.75rem; font-size: 0.85rem; }

.template-executive { padding: 2.5rem; border-top: 8px solid var(--accent-color, #0f172a); }
.template-executive .exec-header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #e2e8f0; padding-bottom: 1.5rem; margin-bottom: 1.5rem; }

.template-serif { padding: 3rem; font-family: 'Merriweather', 'Lora', serif; line-height: 1.6; }
.template-serif .serif-header { text-align: center; margin-bottom: 2rem; }
.template-serif .serif-title { font-size: 2.2rem; font-weight: 700; color: var(--accent-color, #1e293b); }

.template-timeline { padding: 2.5rem; }
.template-timeline .timeline-item { position: relative; padding-left: 1.5rem; border-left: 2px solid var(--accent-color, #2563eb); margin-bottom: 1.25rem; }
.template-timeline .timeline-dot { position: absolute; left: -6px; top: 4px; width: 10px; height: 10px; border-radius: 50%; background: var(--accent-color, #2563eb); }

/* Europass Template */
.template-europass { padding: 2rem; border-left: 12px solid var(--accent-color, #2563eb); min-height: 297mm; }
.template-europass .europass-header { display: flex; align-items: center; gap: 1.5rem; border-bottom: 2px dashed #cbd5e1; padding-bottom: 1.25rem; margin-bottom: 1.5rem; }

/* Sleek Dark Mode Template */
.template-sleek-dark { background: #0f172a !important; color: #f8fafc !important; padding: 2.5rem; min-height: 297mm; }
.template-sleek-dark h3 { color: var(--accent-color, #38bdf8) !important; border-bottom-color: var(--accent-color, #38bdf8) !important; }

/* Infographic & Grid Templates */
.template-infographic { padding: 2rem; display: grid; grid-template-columns: 1fr 2fr; gap: 1.5rem; }
.template-minimal-grid { padding: 2.5rem; display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }


/* Page Break Controls */
.page-break-before { page-break-before: always !important; break-before: page !important; margin-top: 2rem !important; }
.page-break-avoid { page-break-inside: avoid !important; break-inside: avoid !important; }

@media print {
  body { background: #ffffff !important; margin: 0 !important; padding: 0 !important; }
  .app-header, .editor-panel, .preview-toolbar, .mobile-view-toggle, .blogger-hidden-section { display: none !important; }
  .app-container { height: auto !important; display: block !important; }
  .preview-panel { background: transparent !important; padding: 0 !important; margin: 0 !important; width: 100% !important; }
  .resume-paper { box-shadow: none !important; width: 100% !important; margin: 0 !important; padding: 0 !important; page-break-after: avoid; }
}

body.script:
    //

