        function getExportFilename(extension) {
      const name = (resumeData.personal.fullName || "Document").replace(/\s+/g, "_");
      const isCoverLetter = resumeData.settings.template === "coverletter";
      const docType = isCoverLetter ? "CoverLetter" : "Resume";
      return `${name}_${docType}_GoodBuilderCV.${extension}`;
    }

    function generateId() { return '_' + Math.random().toString(36).substr(2, 9); }

    document.addEventListener('DOMContentLoaded', () => {
      loadFromLocalStorage();
      loadCustomTemplatesFromLocalStorage();
      updateTemplateDropdownOptions();
      syncFormFields();
      renderAllLists();
      renderCustomTemplatesLibrary();
      renderResume();
    });

    function saveToLocalStorage() {
      try { localStorage.setItem('goodbuilder_cv_data', JSON.stringify(resumeData)); } catch (e) {}
    }

    function loadFromLocalStorage() {
      try {
        const saved = localStorage.getItem('goodbuilder_cv_data');
        resumeData = saved ? JSON.parse(saved) : JSON.parse(JSON.stringify(sampleData));
      } catch (e) {
        resumeData = JSON.parse(JSON.stringify(sampleData));
      }
    }

    function saveCustomTemplatesToLocalStorage() {
      try { localStorage.setItem('goodbuilder_custom_templates', JSON.stringify(userCustomTemplates)); } catch (e) {}
    }

    function loadCustomTemplatesFromLocalStorage() {
      try {
        const saved = localStorage.getItem('goodbuilder_custom_templates');
        userCustomTemplates = saved ? JSON.parse(saved) : [];
      } catch (e) { userCustomTemplates = []; }
