    function loadIndustryPreset(key) {
      if (!key) return;
      if (confirm(`Load the ${key.toUpperCase()} Industry Preset? Current unsaved changes will be replaced.`)) {
        const preset = industryPresets[key] || sampleData;
        resumeData = JSON.parse(JSON.stringify(preset));
        syncFormFields();
        renderAllLists();
        renderResume();
        saveToLocalStorage();
        document.getElementById("select-preset-industry").value = "";
      }
    }

    function loadSampleData() {
      if (confirm('Load sample data into Good Builder CV?')) {
        resumeData = JSON.parse(JSON.stringify(sampleData));
        syncFormFields();
        renderAllLists();
        renderResume();
        saveToLocalStorage();
      }
    }

    function clearData() {
      if (confirm('Clear all resume data?')) {
        resumeData = {
          personal: { fullName: '', jobTitle: '', email: '', phone: '', location: '', website: '', photo: '' },
          summary: '', experience: [], education: [], skills: [], projects: [], languages: [], certifications: [],
          socials: [], references: [], hobbies: [], customSections: [],
          sectionOrder: ['summary', 'experience', 'education', 'skills', 'projects', 'languages', 'certifications', 'socials', 'references', 'hobbies', 'custom'], columnAllocations: { skills: 'left', languages: 'left', hobbies: 'left', socials: 'left' }, settings: { template: 'modern', accentColor: '#2563eb', fontFamily: 'Inter', fontSize: '14px', margin: 'normal' }
        };
        syncFormFields();
        renderAllLists();
        renderResume();
        saveToLocalStorage();
      }
    }

    function exportJSON() {
      const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(resumeData, null, 2));
      const downloadAnchor = document.createElement('a');
      downloadAnchor.setAttribute('href', dataStr);
      downloadAnchor.setAttribute('download', getExportFilename('json'));
      document.body.appendChild(downloadAnchor);
      downloadAnchor.click();
      downloadAnchor.remove();
    }

    function triggerImportJSON() { document.getElementById('json-input').click(); }

    function importJSON(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const imported = JSON.parse(e.target.result);
          if (imported && imported.personal) {
            resumeData = imported;
            syncFormFields();
            renderAllLists();
            renderResume();
            saveToLocalStorage();
            alert('Good Builder CV data imported!');
          }
        } catch (err) { alert('Error parsing JSON file.'); }
      };
      reader.readAsText(file);
    }

    function downloadPDF() {
      const element = document.getElementById('resume-preview');
      const filename = getExportFilename('pdf');
      const opt = {
        margin: 0,
        filename: filename,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      html2pdf().set(opt).from(element).save();
    }


            function downloadStandaloneHTML() {
