    function downloadDOCX() {
      const resumeContent = document.getElementById("resume-preview").innerHTML;
      const customCss = document.getElementById("custom-template-style-element").innerHTML;

      let baseCss = "";
      try {
        for (let sheet of document.styleSheets) {
          try {
            for (let rule of sheet.cssRules) {
              baseCss += rule.cssText + "\n";
            }
          } catch(e) {}
        }
      } catch(e) {}

      const header = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
  <meta charset="utf-8"/>
  <title>${escapeXml(resumeData.personal.fullName) || "Resume"} - Good Builder CV</title>
  <style>
    ${baseCss}
    body { margin: 0; padding: 0; background: #ffffff; font-family: "${resumeData.settings.fontFamily || "Inter"}", sans-serif; }
    .cv-link { color: ${resumeData.settings.accentColor || "#2563eb"}; text-decoration: underline; word-break: break-all; }
    .resume-paper { background: #ffffff; width: 100%; margin: 0 auto; box-sizing: border-box; }
    ${customCss}
  </style>
</head>
<body>
  <div class="resume-paper" style="font-family:'${resumeData.settings.fontFamily || "Inter"}', sans-serif; font-size:${resumeData.settings.fontSize || "14px"}; --accent-color:${resumeData.settings.accentColor || "#2563eb"};">
    ${resumeContent}
  </div>
</body>
</html>`;

      const blob = new Blob(["\ufeff", header], {
        type: "application/msword"
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = getExportFilename("doc");
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    }

    function switchTab(tabId) {
      document.querySelectorAll('.editor-tab-btn').forEach(btn => btn.classList.remove('active'));
      document.querySelectorAll('.tab-pane').forEach(pane => pane.classList.remove('active'));
      const selectedBtn = Array.from(document.querySelectorAll('.editor-tab-btn')).find(btn => btn.getAttribute('onclick').includes(tabId));
      if (selectedBtn) selectedBtn.classList.add('active');
      const selectedPane = document.getElementById(`tab-${tabId}`);
      if (selectedPane) selectedPane.classList.add('active');

      if (tabId === 'coverletter') {
        changeTemplate('coverletter');
        if (document.getElementById('select-template')) {
          document.getElementById('select-template').value = 'coverletter';
        }
      }
    }

    function toggleMobileView() {
      const editor = document.getElementById('editor-panel');
      const btnText = document.getElementById('mobile-toggle-text');
      if (editor.style.display === 'none') {
        editor.style.display = 'flex';
        btnText.innerText = 'Preview Resume';
      } else {
        editor.style.display = 'none';
        btnText.innerText = 'Edit Resume';
      }
    }

    function syncFormFields() {
      if (resumeData.coverLetter) {
        document.getElementById("cl-recipient").value = resumeData.coverLetter.recipient || "";
        document.getElementById("cl-company").value = resumeData.coverLetter.company || "";
        document.getElementById("cl-salutation").value = resumeData.coverLetter.salutation || "";
        document.getElementById("cl-body").value = resumeData.coverLetter.body || "";
        document.getElementById("cl-closing").value = resumeData.coverLetter.closing || "";
      }

      document.getElementById('personal-fullName').value = resumeData.personal.fullName || '';
      document.getElementById('personal-jobTitle').value = resumeData.personal.jobTitle || '';
      document.getElementById('personal-email').value = resumeData.personal.email || '';
      document.getElementById('personal-phone').value = resumeData.personal.phone || '';
      document.getElementById('personal-location').value = resumeData.personal.location || '';
      document.getElementById('personal-website').value = resumeData.personal.website || '';
      document.getElementById('personal-photo').value = resumeData.personal.photo || '';
      if (document.getElementById('personal-photoStyle')) document.getElementById('personal-photoStyle').value = resumeData.personal.photoStyle || 'circle';
      document.getElementById('summary-text').value = resumeData.summary || '';

      document.getElementById('select-template').value = resumeData.settings.template || 'modern';
      document.getElementById('select-accent-color').value = resumeData.settings.accentColor || '#2563eb';
      document.getElementById('select-font').value = resumeData.settings.fontFamily || 'Inter';
      document.getElementById('select-font-size').value = resumeData.settings.fontSize || '14px';
      document.getElementById('select-margin').value = resumeData.settings.margin || 'normal';
    }

    function updatePersonalInfo() {
      resumeData.personal.fullName = document.getElementById('personal-fullName').value;
      resumeData.personal.jobTitle = document.getElementById('personal-jobTitle').value;
      resumeData.personal.email = document.getElementById('personal-email').value;
      resumeData.personal.phone = document.getElementById('personal-phone').value;
      resumeData.personal.location = document.getElementById('personal-location').value;
      resumeData.personal.website = document.getElementById('personal-website').value;
      resumeData.personal.photo = document.getElementById('personal-photo').value;
      if (document.getElementById('personal-photoStyle')) resumeData.personal.photoStyle = document.getElementById('personal-photoStyle').value;
      saveToLocalStorage();
      renderResume();
    }

    function handlePhotoUpload(event) {
      const file = event.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          resumeData.personal.photo = e.target.result;
          document.getElementById('personal-photo').value = e.target.result;
          saveToLocalStorage();
          renderResume();
        };
        reader.readAsDataURL(file);
      }
    }

    function updateSummary() {
      resumeData.summary = document.getElementById('summary-text').value;
      saveToLocalStorage();
      renderResume();
    }

    function changeTemplate(val) { resumeData.settings.template = val; saveToLocalStorage(); renderResume(); }
    function changeAccentColor(val) {
      resumeData.settings.accentColor = val;
      document.getElementById('select-accent-color').value = val;
      saveToLocalStorage();
      renderResume();
    }
    function changeFontFamily(val) { resumeData.settings.fontFamily = val; saveToLocalStorage(); renderResume(); }
    function changeFontSize(val) { resumeData.settings.fontSize = val; saveToLocalStorage(); renderResume(); }
    function changeMargin(val) { resumeData.settings.margin = val; saveToLocalStorage(); renderResume(); }

    function changeZoom(scaleVal) {
      const paper = document.getElementById("resume-preview");
      if (paper) {
        paper.style.transform = `scale(${scaleVal})`;
        paper.style.transformOrigin = "top center";
      }
      if (!resumeData.settings) resumeData.settings = {};
      resumeData.settings.zoom = scaleVal;
      saveToLocalStorage();
    }


    /* CUSTOM TEMPLATE STUDIO FUNCTIONS */
    function updateTemplateDropdownOptions() {
      const select = document.getElementById('select-template');
      select.querySelectorAll('option[data-custom="true"]').forEach(opt => opt.remove());
      userCustomTemplates.forEach(ct => {
        const opt = document.createElement('option');
        opt.value = ct.id;
        opt.innerText = `Custom: ${ct.name}`;
        opt.setAttribute('data-custom', 'true');
        select.appendChild(opt);
      });
    }

    function saveCustomTemplate() {
      const name = document.getElementById('custom-template-name').value.trim();
      const css = document.getElementById('custom-template-css').value;
      const html = document.getElementById('custom-template-html').value;
      if (!name || !html) { alert('Please enter both a template name and HTML structure.'); return; }

      const id = 'custom_' + name.toLowerCase().replace(/[^a-z0-9]/g, '_');
      const existingIndex = userCustomTemplates.findIndex(t => t.id === id);
      const newTemplate = { id, name, css, html };

      if (existingIndex >= 0) userCustomTemplates[existingIndex] = newTemplate;
      else userCustomTemplates.push(newTemplate);

      saveCustomTemplatesToLocalStorage();
      updateTemplateDropdownOptions();
      renderCustomTemplatesLibrary();
      changeTemplate(id);
      alert(`Custom Template "${name}" saved and set as current!`);
    }

    function renderCustomTemplatesLibrary() {
      const container = document.getElementById('custom-templates-library');
      if (!container) return;
      container.innerHTML = '';
      if (!userCustomTemplates.length) {
        container.innerHTML = '<div style="font-size:0.8rem; color:#94a3b8;">No custom templates saved yet.</div>';
        return;
      }
      userCustomTemplates.forEach(t => {
        const item = document.createElement('div');
        item.style.cssText = 'background:#f8fafc; border:1px solid #e2e8f0; padding:0.6rem 0.8rem; border-radius:0.375rem; margin-bottom:0.5rem; display:flex; justify-content:space-between; align-items:center;';
        item.innerHTML = `
          <span style="font-size:0.85rem; font-weight:600;">${escapeXml(t.name)}</span>
          <div style="display:flex; gap:0.25rem;">
            <button class="btn btn-primary btn-sm" onclick="applyCustomTemplate('${t.id}')">Apply</button>
            <button class="btn btn-danger btn-sm" onclick="deleteCustomTemplate('${t.id}')"><i class="fa-solid fa-trash"></i></button>
          </div>
        `;
        container.appendChild(item);
      });
    }

    function applyCustomTemplate(id) {
      const t = userCustomTemplates.find(x => x.id === id);
      if (t) {
        document.getElementById('custom-template-name').value = t.name;
        document.getElementById('custom-template-css').value = t.css;
        document.getElementById('custom-template-html').value = t.html;
        changeTemplate(id);
      }
    }

    function deleteCustomTemplate(id) {
      if (confirm('Delete this custom template?')) {
        userCustomTemplates = userCustomTemplates.filter(t => t.id !== id);
        saveCustomTemplatesToLocalStorage();
        updateTemplateDropdownOptions();
        renderCustomTemplatesLibrary();
        if (resumeData.settings.template === id) changeTemplate('modern');
      }
    }

    function exportCustomTemplate() {
      const name = document.getElementById('custom-template-name').value.trim() || 'Custom_Template';
      const css = document.getElementById('custom-template-css').value;
      const html = document.getElementById('custom-template-html').value;
      const exportData = { type: 'goodbuilder_template', name, css, html };
      const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchor = document.createElement('a');
      downloadAnchor.setAttribute('href', dataStr);
      downloadAnchor.setAttribute('download', `${name.replace(/\s+/g, '_')}_template.json`);
      document.body.appendChild(downloadAnchor);
      downloadAnchor.click();
      downloadAnchor.remove();
    }

    function triggerImportCustomTemplate() { document.getElementById('custom-template-file-input').click(); }

    function importCustomTemplate(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const imported = JSON.parse(e.target.result);
          if (imported && imported.name && imported.html) {
            document.getElementById('custom-template-name').value = imported.name;
            document.getElementById('custom-template-css').value = imported.css || '';
            document.getElementById('custom-template-html').value = imported.html;
            saveCustomTemplate();
          } else { alert('Invalid template file format.'); }
        } catch (err) { alert('Error parsing template JSON.'); }
      };
      reader.readAsText(file);
    }

    // FORM LIST RENDERERS
    function renderExperienceList() {
      const container = document.getElementById('experience-list');
      container.innerHTML = '';
      resumeData.experience.forEach((item, index) => {
        const card = document.createElement('div');
        card.className = 'entry-card';
        card.innerHTML = `
          <div class="entry-card-header">
            <span class="entry-card-title">${escapeXml(item.title || 'Role')} at ${escapeXml(item.company || 'Company')}</span>
            <div class="entry-actions">
              <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, -1)"><i class="fa-solid fa-arrow-up"></i></button>
              <button class="btn btn-outline btn-sm" onclick="moveItem('experience', ${index}, 1)"><i class="fa-solid fa-arrow-down"></i></button>
              <button class="btn btn-danger btn-sm" onclick="removeItem('experience', '${item.id}')"><i class="fa-solid fa-trash"></i></button>
            </div>
          </div>
          <div class="form-group"><label>Job Title</label><input type="text" value="${escapeAttr(item.title)}" oninput="updateItemField('experience', '${item.id}', 'title', this.value)"/></div>
          <div class="form-row">
            <div class="form-group"><label>Company</label><input type="text" value="${escapeAttr(item.company)}" oninput="updateItemField('experience', '${item.id}', 'company', this.value)"/></div>
            <div class="form-group"><label>Location</label><input type="text" value="${escapeAttr(item.location)}" oninput="updateItemField('experience', '${item.id}', 'location', this.value)"/></div>
          </div>
          <div class="form-row">
            <div class="form-group"><label>Start Date</label><input type="month" value="${item.startDate || ''}" oninput="updateItemField('experience', '${item.id}', 'startDate', this.value)" onchange="updateItemField('experience', '${item.id}', 'startDate', this.value)"/></div>
            <div class="form-group"><label>End Date</label><input type="month" value="${item.endDate || ''}" ${item.current ? 'disabled' : ''} oninput="updateItemField('experience', '${item.id}', 'endDate', this.value)" onchange="updateItemField('experience', '${item.id}', 'endDate', this.value)"/></div>
          </div>
          <div class="checkbox-group">
            <input type="checkbox" id="exp-curr-${item.id}" ${item.current ? 'checked' : ''} onchange="updateExperienceCurrent('${item.id}', this.checked)"/>
            <label for="exp-curr-${item.id}">I currently work here</label>
          </div>
          <div class="form-group" style="margin-top:0.75rem;"><label>Description &amp; Bullet Points</label><textarea rows="3" oninput="updateItemField('experience', '${item.id}', 'description', this.value)">${escapeXml(item.description || '')}</textarea></div>
        `;
        container.appendChild(card);
      });
    }

    function updateExperienceCurrent(id, isChecked) {
      const item = resumeData.experience.find(i => i.id === id);
      if (item) {
        item.current = isChecked;
        if (isChecked) item.endDate = '';
        renderExperienceList();
        saveToLocalStorage();
        renderResume();
      }
    }

