    function addCustomSection() {
      resumeData.customSections.push({ id: generateId(), heading: 'Custom Section', items: [] });
      renderCustomSectionsList(); saveToLocalStorage(); renderResume();
    }

    function moveCustomSection(index, direction) {
      const arr = resumeData.customSections;
      const targetIndex = index + direction;
      if (targetIndex >= 0 && targetIndex < arr.length) {
        const temp = arr[index]; arr[index] = arr[targetIndex]; arr[targetIndex] = temp;
        renderCustomSectionsList(); saveToLocalStorage(); renderResume();
      }
    }

    function removeCustomSection(secId) {
      resumeData.customSections = resumeData.customSections.filter(s => s.id !== secId);
      renderCustomSectionsList(); saveToLocalStorage(); renderResume();
    }

    function updateCustomHeading(secId, val) {
      const sec = resumeData.customSections.find(s => s.id === secId);
      if (sec) sec.heading = val;
      saveToLocalStorage(); renderResume();
    }

    function addCustomItem(secId) {
      const sec = resumeData.customSections.find(s => s.id === secId);
      if (sec) {
        sec.items.push({ id: generateId(), title: '', subtitle: '', date: '', location: '', description: '' });
        renderCustomSectionsList(); saveToLocalStorage(); renderResume();
      }
    }

    function moveCustomItem(secId, itemIndex, direction) {
      const sec = resumeData.customSections.find(s => s.id === secId);
      if (sec) {
        const targetIndex = itemIndex + direction;
        if (targetIndex >= 0 && targetIndex < sec.items.length) {
          const temp = sec.items[itemIndex]; sec.items[itemIndex] = sec.items[targetIndex]; sec.items[targetIndex] = temp;
          renderCustomSectionsList(); saveToLocalStorage(); renderResume();
        }
      }
    }

    function removeCustomItem(secId, itemId) {
      const sec = resumeData.customSections.find(s => s.id === secId);
      if (sec) {
        sec.items = sec.items.filter(i => i.id !== itemId);
        renderCustomSectionsList(); saveToLocalStorage(); renderResume();
      }
    }

    function updateCustomItemField(secId, itemId, field, val) {
      const sec = resumeData.customSections.find(s => s.id === secId);
      if (sec) {
        const item = sec.items.find(i => i.id === itemId);
        if (item) item[field] = val;
        saveToLocalStorage(); renderResume();
      }
    }

