      container.innerHTML = "";
      if (!resumeData.sectionOrder) {
        resumeData.sectionOrder = ["summary", "experience", "education", "skills", "projects", "languages", "certifications", "socials", "references", "hobbies", "custom"];
      }
      const names = {
        summary: "Professional Summary",
        experience: "Work Experience",
        education: "Education",
        skills: "Skills & Expertise",
        projects: "Projects",
        languages: "Languages",
        certifications: "Certifications",
        socials: "Social & Web Links",
        references: "References",
        hobbies: "Hobbies",
        custom: "Custom Sections", coverletter: "Cover Letter Attachment"
      };
      resumeData.sectionOrder.forEach((secKey, index) => {
        const item = document.createElement("div");
        item.style.cssText = "background:#f8fafc; border:1px solid #cbd5e1; padding:0.5rem 0.75rem; border-radius:0.375rem; margin-bottom:0.35rem; display:flex; justify-content:space-between; align-items:center;";
        const currentCol = (resumeData.columnAllocations && resumeData.columnAllocations[secKey]) || "right";
        item.innerHTML = `
          <span style="font-size:0.85rem; font-weight:600; color:#334155;"><i class="fa-solid fa-grip-vertical" style="color:#94a3b8; margin-right:0.5rem;"></i>${names[secKey] || secKey}</span>
          <div class="entry-actions" style="align-items:center; gap:0.25rem;">
            <select class="btn btn-outline btn-sm" style="padding:2px 4px; font-size:0.75rem;" onchange="toggleSectionColumn('${secKey}', this.value)">
              <option value="right" ${currentCol === "right" ? "selected" : ""}>Main (Right)</option>
              <option value="left" ${currentCol === "left" ? "selected" : ""}>Sidebar (Left)</option>
            </select>
            <button class="btn btn-outline btn-sm" onclick="moveSectionOrder(${index}, -1)"><i class="fa-solid fa-arrow-up"></i></button>
            <button class="btn btn-outline btn-sm" onclick="moveSectionOrder(${index}, 1)"><i class="fa-solid fa-arrow-down"></i></button>
          </div>
        `;
        container.appendChild(item);
      });
    }


    function toggleSectionColumn(secKey, colVal) {
      if (!resumeData.columnAllocations) resumeData.columnAllocations = {};
      resumeData.columnAllocations[secKey] = colVal;
      saveToLocalStorage();
      renderResume();
    }

    function moveSectionOrder(index, direction) {
      if (!resumeData.sectionOrder) return;
      const targetIndex = index + direction;
      if (targetIndex >= 0 && targetIndex < resumeData.sectionOrder.length) {
        const temp = resumeData.sectionOrder[index];
        resumeData.sectionOrder[index] = resumeData.sectionOrder[targetIndex];
        resumeData.sectionOrder[targetIndex] = temp;
        renderSectionOrderManager();
        saveToLocalStorage();
        renderResume();
      }
    }


