    function getI18nText(key) {
      const lang = (resumeData.settings && resumeData.settings.language) || "en";
      return (translations[lang] && translations[lang][key]) || translations["en"][key] || key;
    }

    function renderOrderedSectionsHTML(excludeKeys = []) {
      if (!resumeData.sectionOrder) {
        resumeData.sectionOrder = ["summary", "experience", "education", "skills", "projects", "languages", "certifications", "socials", "references", "hobbies", "custom"];
      }
      return resumeData.sectionOrder.map(secKey => {
        if (excludeKeys.includes(secKey)) return "";
        if (secKey === "summary" && resumeData.summary) return getSectionHTML(getI18nText("summary"), `<p style="margin:0; color:inherit;">${escapeXml(resumeData.summary)}</p>`);
        if (secKey === "experience") return getSectionHTML(getI18nText("experience"), renderCommonExperience());
        if (secKey === "education") return getSectionHTML(getI18nText("education"), renderCommonEducation());
        if (secKey === "skills") return getSectionHTML(getI18nText("skills"), renderCommonSkills());
        if (secKey === "projects") return getSectionHTML(getI18nText("projects"), renderCommonProjects());
        if (secKey === "languages") return getSectionHTML(getI18nText("languages"), renderCommonLanguages());
        if (secKey === "certifications") return getSectionHTML(getI18nText("certifications"), renderCommonCertifications());
        if (secKey === "socials") return getSectionHTML(getI18nText("socials"), renderCommonSocials());
        if (secKey === "references") return getSectionHTML(getI18nText("references"), renderCommonReferences());
        if (secKey === "hobbies") return getSectionHTML(getI18nText("hobbies"), `<div style="display:flex; flex-wrap:wrap; gap:0.4rem;">${resumeData.hobbies.map(h => `<span style="background:#f1f5f9; color:#0f172a; padding:0.25rem 0.6rem; border-radius:4px; font-weight:600; font-size:0.8rem; border:1px solid #e2e8f0;">${escapeXml(h.name)}</span>`).join("")}</div>`);
        if (secKey === "custom") return renderCommonCustom();
        if (secKey === "coverletter" && resumeData.coverLetter && resumeData.coverLetter.body) {
          const cl = resumeData.coverLetter;
          return getSectionHTML("Cover Letter", `<div style="font-size:0.9rem; line-height:1.6; color:#334155;"><p><strong>To: ${escapeXml(cl.recipient || "")} (${escapeXml(cl.company || "")})</strong></p><p><em>${escapeXml(cl.salutation || "")}</em></p><p style="white-space:pre-line;">${escapeXml(cl.body || "")}</p><p><strong>${escapeXml(cl.closing || "")}</strong></p></div>`, "coverletter");
        }
        return "";
      }).join("");
    }



