    function renderAIPrompts(industryKey) {
      const data = aiPromptData[industryKey] || aiPromptData.tech;
      const verbsBox = document.getElementById("ai-action-verbs-list");
      const bulletsBox = document.getElementById("ai-bullet-templates-list");

      if (verbsBox) {
        verbsBox.innerHTML = data.verbs.map(v => `<span style="background:#e0f2fe; color:#0369a1; padding:3px 8px; border-radius:12px; font-size:0.75rem; font-weight:600; cursor:pointer;" title="Click to copy" onclick="navigator.clipboard.writeText('${v}')">${v}</span>`).join("");
      }

      if (bulletsBox) {
        bulletsBox.innerHTML = data.bullets.map(b => `
          <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:0.6rem 0.8rem; border-radius:0.375rem; margin-bottom:0.5rem; font-size:0.8rem; color:#334155; display:flex; justify-content:space-between; align-items:center;">
            <span>${escapeXml(b)}</span>
            <button class="btn btn-outline btn-sm" onclick="navigator.clipboard.writeText('${escapeAttr(b)}'); alert('Copied!');"><i class="fa-solid fa-copy"></i> Copy</button>
          </div>
        `).join("");
      }
    }


    function runBulletProofreader() {
      const container = document.getElementById("ai-proofreader-feedback");
      if (!container) return;

      let items = [];
      const expList = resumeData.experience || [];
      if (!expList.length) {
        container.innerHTML = `<div style="font-size:0.8rem; color:#94a3b8;">Add work experience bullet points to run proofreading analysis.</div>`;
        return;
      }

      expList.forEach((exp, idx) => {
        const text = exp.description || "";
        if (!text) return;
        const bullets = text.split("\n").filter(b => b.trim().length > 0);
        bullets.forEach((bullet, bIdx) => {
          let warnings = [];
          if (!/^[•\-*\d]/i.test(bullet.trim()) && !/^[A-Z]/i.test(bullet.trim())) {
            warnings.push("Bullet point should start with an action verb or bullet symbol.");
          }
          if (!/\d+|%|\$|M|K/i.test(bullet)) {
            warnings.push("Consider adding quantifiable metrics or impact numbers (e.g., %, $, numbers).");
          }
          if (bullet.length < 25) {
            warnings.push("Bullet point is too short. Elaborate on your task and result.");
          }
          items.push({
            role: exp.title || "Job #" + (idx + 1),
            bullet: bullet,
            warnings: warnings
          });
        });
      });

      if (!items.length) {
        container.innerHTML = `<div style="font-size:0.8rem; color:#10b981; font-weight:600;"><i class="fa-solid fa-circle-check"></i> All bullet points look well-formatted!</div>`;
        return;
      }

      container.innerHTML = items.map(item => `
        <div style="background:#f8fafc; border:1px solid #cbd5e1; padding:0.6rem; border-radius:0.375rem; margin-bottom:0.5rem; font-size:0.8rem;">
          <div style="font-weight:700; color:#0f172a; margin-bottom:0.25rem;">${escapeXml(item.role)}: "${escapeXml(item.bullet)}"</div>
          ${item.warnings.length ? item.warnings.map(w => `<div style="color:#d97706; font-size:0.75rem;"><i class="fa-solid fa-triangle-exclamation"></i> ${escapeXml(w)}</div>`).join("") : `<div style="color:#10b981; font-size:0.75rem;"><i class="fa-solid fa-check"></i> Great impact bullet point!</div>`}
        </div>
      `).join("");
    }


    function analyzeJobKeywords(jdText) {
      const resultsBox = document.getElementById("ats-keyword-match-results");
      if (!resultsBox) return;
      if (!jdText || jdText.trim().length < 20) {
        resultsBox.innerHTML = `<div style="font-size:0.8rem; color:#94a3b8;">Paste a job description above to calculate keyword match rate.</div>`;
        return;
      }

      // Build resume corpus text
      const p = resumeData.personal;
      let resumeCorpus = `${p.fullName} ${p.jobTitle} ${resumeData.summary} ` +
        (resumeData.experience || []).map(e => `${e.title} ${e.company} ${e.description}`).join(" ") + " " +
        (resumeData.skills || []).map(s => s.name).join(" ") + " " +
        (resumeData.projects || []).map(pr => `${pr.title} ${pr.tech} ${pr.description}`).join(" ");

      resumeCorpus = resumeCorpus.toLowerCase();

      // Extract unique words > 3 letters from JD
      const stopwords = new Set(["the", "and", "for", "with", "that", "this", "from", "have", "your", "will", "are", "their", "about", "work", "must", "they", "been", "team"]);
      const jdWords = jdText.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(w => w.length > 3 && !stopwords.has(w));
      const wordCounts = {};
      jdWords.forEach(w => wordCounts[w] = (wordCounts[w] || 0) + 1);

      const topKeywords = Object.keys(wordCounts).sort((a,b) => wordCounts[b] - wordCounts[a]).slice(0, 15);
      let matchedCount = 0;
      const keyItems = topKeywords.map(kw => {
        const found = resumeCorpus.includes(kw);
        if (found) matchedCount++;
        return `<span style="background:${found ? "#dcfce7" : "#fee2e2"}; color:${found ? "#166534" : "#991b1b"}; padding:2px 8px; border-radius:12px; font-size:0.75rem; font-weight:600; margin-right:4px; margin-bottom:4px; display:inline-block;">${found ? "✓" : "✗"} ${escapeXml(kw)}</span>`;
      });

      const matchPercentage = topKeywords.length ? Math.round((matchedCount / topKeywords.length) * 100) : 0;

      resultsBox.innerHTML = `
        <div style="font-size:0.85rem; font-weight:700; color:#0f172a; margin-bottom:0.5rem;">
          Keyword Match Rate: <span style="color:${matchPercentage >= 70 ? "#10b981" : "#d97706"};">${matchPercentage}%</span> (${matchedCount}/${topKeywords.length} terms found)
        </div>
        <div>${keyItems.join("")}</div>
      `;
    }

    function calculateATSScore() {
      let score = 0;
      let checklist = [];

      const p = resumeData.personal;
      if (p.fullName && p.fullName.trim().length > 2) { score += 10; checklist.push({ pass: true, text: "Full Name provided" }); }
      else { checklist.push({ pass: false, text: "Add your Full Name" }); }

      if (p.email && p.email.includes("@")) { score += 10; checklist.push({ pass: true, text: "Valid Email address provided" }); }
      else { checklist.push({ pass: false, text: "Add a valid Email address" }); }

      if (p.phone && p.phone.trim().length > 5) { score += 10; checklist.push({ pass: true, text: "Phone number included" }); }
      else { checklist.push({ pass: false, text: "Add a Phone number" }); }

      if (resumeData.summary && resumeData.summary.length > 50) { score += 15; checklist.push({ pass: true, text: "Professional Summary is detailed" }); }
      else { checklist.push({ pass: false, text: "Expand Professional Summary to at least 50 characters" }); }

      if (resumeData.experience && resumeData.experience.length >= 2) { score += 20; checklist.push({ pass: true, text: "Work Experience has 2+ detailed entries" }); }
      else { checklist.push({ pass: false, text: "Add at least 2 Work Experience entries" }); }

      if (resumeData.skills && resumeData.skills.length >= 5) { score += 15; checklist.push({ pass: true, text: "Key Skills section has 5+ items" }); }
      else { checklist.push({ pass: false, text: "List at least 5 key Technical or Soft Skills" }); }

      if (resumeData.education && resumeData.education.length >= 1) { score += 10; checklist.push({ pass: true, text: "Education history included" }); }
      else { checklist.push({ pass: false, text: "Add Education history" }); }

      if (resumeData.projects && resumeData.projects.length >= 1) { score += 10; checklist.push({ pass: true, text: "Projects / Achievements included" }); }
      else { checklist.push({ pass: false, text: "Include at least 1 Project or key achievement" }); }

      const display = document.getElementById("ats-score-display");
      const badge = document.getElementById("ats-score-badge");
      const container = document.getElementById("ats-checklist-items");

      if (display && container) {
        display.innerText = score + "%";
        if (score >= 80) { badge.innerText = "High ATS Match"; badge.style.background = "#dcfce7"; badge.style.color = "#166534"; }
        else if (score >= 50) { badge.innerText = "Moderate ATS Match"; badge.style.background = "#fef9c3"; badge.style.color = "#854d0e"; }
        else { badge.innerText = "Needs Optimization"; badge.style.background = "#fee2e2"; badge.style.color = "#991b1b"; }

        container.innerHTML = checklist.map(c => `
          <div style="display:flex; align-items:center; gap:0.5rem; font-size:0.85rem; margin-bottom:0.5rem;">
            <i class="fa-solid ${c.pass ? "fa-circle-check" : "fa-circle-xmark"}" style="color:${c.pass ? "#10b981" : "#ef4444"};"></i>
            <span style="color:${c.pass ? "#334155" : "#991b1b"};">${escapeXml(c.text)}</span>
          </div>
        `).join("");
      }
    }

    function updateCoverLetter() {
      if (!resumeData.coverLetter) resumeData.coverLetter = {};
      resumeData.coverLetter.recipient = document.getElementById("cl-recipient").value;
      resumeData.coverLetter.company = document.getElementById("cl-company").value;
      resumeData.coverLetter.salutation = document.getElementById("cl-salutation").value;
      resumeData.coverLetter.body = document.getElementById("cl-body").value;
      resumeData.coverLetter.closing = document.getElementById("cl-closing").value;
      saveToLocalStorage();
      renderResume();
    }

    function renderAllLists() { calculateATSScore(); runBulletProofreader(); renderAIPrompts('tech'); renderSectionOrderManager();
      renderExperienceList(); renderEducationList(); renderSkillsList(); renderProjectsList();
      renderLanguagesList(); renderCertificationsList(); renderSocialsList(); renderReferencesList();
      renderHobbiesList(); renderCustomSectionsList();
    }

    function updateItemField(category, id, field, val) {
      const item = resumeData[category].find(i => i.id === id);
      if (item) { item[field] = val; saveToLocalStorage(); renderResume(); }
    }

    function removeItem(category, id) {
      resumeData[category] = resumeData[category].filter(i => i.id !== id);
      renderAllLists(); saveToLocalStorage(); renderResume();
    }

    function moveItem(category, index, direction) {
      const arr = resumeData[category];
      const targetIndex = index + direction;
      if (targetIndex >= 0 && targetIndex < arr.length) {
        const temp = arr[index]; arr[index] = arr[targetIndex]; arr[targetIndex] = temp;
        renderAllLists(); saveToLocalStorage(); renderResume();
      }
    }

    function escapeXml(str) { return str ? String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : ''; }
    function escapeAttr(str) { return str ? String(str).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : ''; }

    function formatDate(dateStr) {
      if (!dateStr) return '';
      const [year, month] = dateStr.split('-');
      if (!year) return dateStr;
      if (!month) return year;
      const date = new Date(year, month - 1);
      return date.toLocaleString('default', { month: 'short' }) + ' ' + year;
    }

    function formatURL(url) {
      if (!url) return '';
      if (!/^https?:\/\//i.test(url)) return 'https://' + url;
      return url;
    }

    function formatMailto(email) {
      if (!email) return '';
      return 'mailto:' + email.trim();
    }

    function formatTel(phone) {
      if (!phone) return '';
      return 'tel:' + phone.replace(/[^\d+]/g, '');
    }

    // SECTION RENDER HELPERS
    function getSectionHTML(title, content) {
      if (!content) return '';
      return `<div style="margin-bottom:1.25rem;">
        <h3 style="color:var(--accent-color); font-size:1.05rem; font-weight:700; border-bottom:2px solid var(--accent-color); padding-bottom:3px; margin-bottom:0.6rem; text-transform:uppercase;">${escapeXml(title)}</h3>
        ${content}
      </div>`;
    }

    function renderCommonExperience() {
      if (!resumeData.experience.length) return '';
      return resumeData.experience.map(e => `
        <div style="margin-bottom:0.85rem;">
          <div style="display:flex; justify-content:space-between; font-weight:700;">
            <span style="color:#0f172a;">${escapeXml(e.title)}</span>
            <span style="color:var(--accent-color); font-size:0.8rem;">${formatDate(e.startDate)}${e.startDate || e.endDate || e.current ? ' - ' : ''}${e.current ? 'Present' : formatDate(e.endDate)}</span>
          </div>
          <div style="font-size:0.85rem; color:#475569; font-weight:500;">${escapeXml(e.company)} ${e.location ? `• ${escapeXml(e.location)}` : ''}</div>
          <div style="font-size:0.85rem; color:#334155; margin-top:0.25rem; white-space:pre-line;">${escapeXml(e.description)}</div>
        </div>
      `).join('');
