          </div>
          <div style="font-size:0.85rem; color:#475569;">${escapeXml(e.institution)} ${e.location ? `(${escapeXml(e.location)})` : ''} ${e.gpa ? `• GPA: ${escapeXml(e.gpa)}` : ''}</div>
