        ${resumeData.skills.map(s => `<span style="background:#f1f5f9; color:#0f172a; padding:0.25rem 0.6rem; border-radius:4px; font-weight:600; font-size:0.8rem; border:1px solid #e2e8f0;">${escapeXml(s.name)} ${s.level ? `(${s.level}%)` : ''}</span>`).join('')}
