            ${p.link ? `<a class="cv-link" href="${escapeAttr(formatURL(p.link))}" target="_blank" style="color:var(--accent-color); font-size:0.8rem; text-decoration:none;">Link ↗</a>` : ''}
          </div>
          ${p.tech ? `<div style="font-size:0.75rem; color:var(--accent-color); font-weight:600;">${escapeXml(p.tech)}</div>` : ''}
          <div style="font-size:0.85rem; color:#334155;">${escapeXml(p.description)}</div>
