    function renderCommonLanguages() {
      if (!resumeData.languages.length) return '';
      return `<div style="display:grid; grid-template-columns:1fr 1fr; gap:0.5rem;">
        ${resumeData.languages.map(l => `<div style="font-size:0.85rem;"><strong>${escapeXml(l.name)}:</strong> ${escapeXml(l.level)}</div>`).join('')}
      </div>`;
    }

    function renderCommonCertifications() {
      if (!resumeData.certifications.length) return '';
