        <div style="display:flex; justify-content:space-between; font-size:0.85rem; margin-bottom:0.35rem;">
          <div><strong>${escapeXml(c.title)}</strong> – ${escapeXml(c.issuer)} ${c.url ? `<a class="cv-link" href="${escapeAttr(formatURL(c.url))}" target="_blank">↗</a>` : ''}</div>
          <span style="color:#64748b; font-size:0.8rem;">${formatDate(c.date)}</span>
        </div>
      `).join('');
