    function renderCommonSocials() {
      if (!resumeData.socials.length) return '';
      return `<div style="display:flex; flex-wrap:wrap; gap:0.75rem; font-size:0.85rem;">
        ${resumeData.socials.map(s => `<div><strong>${escapeXml(s.platform)}:</strong> <a class="cv-link" href="${escapeAttr(formatURL(s.url || s.username))}" target="_blank">${escapeXml(s.username || s.url)}</a></div>`).join('')}
      </div>`;
    }

    function renderCommonReferences() {
      if (!resumeData.references.length) return '';
      return `<div style="display:grid; grid-template-columns:1fr 1fr; gap:0.75rem;">
        ${resumeData.references.map(r => `<div style="font-size:0.85rem;"><strong>${escapeXml(r.name)}</strong><br/><span style="color:#475569;">${escapeXml(r.title)}</span><br/><span style="color:#64748b; font-size:0.8rem;">${escapeXml(r.contact)}</span></div>`).join('')}
      </div>`;
    }

    function renderCommonCustom() {
      if (!resumeData.customSections || !resumeData.customSections.length) return '';
      return resumeData.customSections.map(sec => {
        if (!sec.items || !sec.items.length) return '';
        const itemsHTML = sec.items.map(i => `
          <div style="margin-bottom:0.6rem;">
            <div style="display:flex; justify-content:space-between; font-weight:700;"><span>${escapeXml(i.title)}</span><span style="color:#64748b; font-size:0.8rem;">${escapeXml(i.date)}</span></div>
            <div style="font-size:0.85rem; color:#475569; font-weight:500;">${escapeXml(i.subtitle || '')} ${i.location ? `• ${escapeXml(i.location)}` : ''}</div>
            ${i.description ? `<div style="font-size:0.85rem; color:#334155; margin-top:0.2rem;">${escapeXml(i.description)}</div>` : ''}
          </div>
        `).join('');
        return getSectionHTML(sec.heading, itemsHTML);
      }).join('');
    }

    // MAIN RESUME RENDER ENGINE

    function renderQRCodeElement() {
      const url = resumeData.personal.website || (resumeData.socials.length ? resumeData.socials[0].url : "");
      if (!url) return "";
      return `<div style="display:flex; flex-direction:column; align-items:center; justify-content:center; margin-top:1rem; padding:0.5rem; background:#fff; border-radius:6px; width:fit-content; border:1px solid #e2e8f0;">
        <div id="qrcode-canvas" style="width:70px; height:70px;"></div>
        <span style="font-size:0.65rem; color:#64748b; font-weight:600; margin-top:4px;">Scan Portfolio</span>
      </div>`;
    }

    function generateQRCodeImage() {
      setTimeout(() => {
        const qrBox = document.getElementById("qrcode-canvas");
        if (qrBox && typeof QRCode !== "undefined") {
          qrBox.innerHTML = "";
          const url = resumeData.personal.website || (resumeData.socials.length ? resumeData.socials[0].url : "");
          if (url) {
            new QRCode(qrBox, {
              text: url,
              width: 70,
              height: 70,
              colorDark: "#0f172a",
              colorLight: "#ffffff",
              correctLevel: QRCode.CorrectLevel.M
            });
          }
        }
      }, 100);
    }


    function renderCoverLetterTemplate(p, padding) {
      const cl = resumeData.coverLetter || { recipient: "Hiring Manager", company: "Company Name", salutation: "Dear Hiring Manager,", body: "Cover letter body content...", closing: "Sincerely,\n" + (p.fullName || "Your Name") };
      return `
        <div style="padding:${padding}; min-height:297mm; display:flex; flex-direction:column; justify-space-between;">
          <div style="border-bottom:2px solid var(--accent-color); padding-bottom:1.5rem; margin-bottom:2rem; display:flex; justify-content:space-between; align-items:center;">
            <div>
              <div style="font-size:2.2rem; font-weight:800; color:#0f172a;">${escapeXml(p.fullName || "Your Name")}</div>
              <div style="font-size:1.1rem; color:var(--accent-color); font-weight:600;">${escapeXml(p.jobTitle || "Profession")}</div>
            </div>
            <div style="text-align:right; font-size:0.85rem; color:#475569;">
              ${p.email ? `<div>${escapeXml(p.email)}</div>` : ""}
              ${p.phone ? `<div>${escapeXml(p.phone)}</div>` : ""}
              ${p.location ? `<div>${escapeXml(p.location)}</div>` : ""}
              ${p.website ? `<div>${escapeXml(p.website)}</div>` : ""}
            </div>
          </div>

          <div style="font-size:0.9rem; color:#334155; line-height:1.7; flex:1;">
            <div style="margin-bottom:1.5rem; font-weight:600;">
              <div>Date: ${new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" })}</div>
              <div style="margin-top:0.5rem; font-weight:700; color:#0f172a;">To: ${escapeXml(cl.recipient || "Hiring Manager")}</div>
              <div>${escapeXml(cl.company || "Company")}</div>
            </div>

            <div style="font-weight:700; font-size:1rem; margin-bottom:1rem; color:#0f172a;">${escapeXml(cl.salutation || "Dear Hiring Manager,")}</div>

            <div style="white-space:pre-line; margin-bottom:2rem; text-align:justify;">${escapeXml(cl.body || "")}</div>

            <div style="white-space:pre-line; font-weight:600; color:#0f172a;">${escapeXml(cl.closing || "Sincerely,\n" + (p.fullName || ""))}</div>
          </div>
        </div>
      `;
    }

    function renderResume() {
      const container = document.getElementById('resume-preview');
      const settings = resumeData.settings;
      const p = resumeData.personal;

      let paddingMap = { compact: '1.5rem', normal: '2.5rem', spacious: '3.5rem' };
      const paddingVal = paddingMap[settings.margin] || '2.5rem';

      container.style.fontFamily = `'${settings.fontFamily}', sans-serif`;
      container.style.fontSize = settings.fontSize || '14px';
      container.style.setProperty('--accent-color', settings.accentColor || '#2563eb');

      const template = settings.template || 'modern';
      let html = '';

      // Check if Custom Studio Template
      const customT = userCustomTemplates.find(t => t.id === template);
      if (customT) {
        document.getElementById('custom-template-style-element').innerHTML = customT.css || '';
        html = renderStudioCustomTemplate(customT, p);
      } else {
        document.getElementById('custom-template-style-element').innerHTML = '';
        if (template === 'modern') html = renderModernTemplate(p, paddingVal);
        else if (template === 'classic') html = renderClassicTemplate(p, paddingVal);
        else if (template === 'minimal') html = renderMinimalTemplate(p, paddingVal);
        else if (template === 'creative') html = renderCreativeTemplate(p, paddingVal);
        else if (template === 'compact') html = renderCompactTemplate(p, paddingVal);
        else if (template === 'executive') html = renderExecutiveTemplate(p, paddingVal);
        else if (template === 'serif') html = renderSerifTemplate(p, paddingVal);
        else if (template === 'timeline') html = renderTimelineTemplate(p, paddingVal);
        else if (template === 'europass') html = renderEuropassTemplate(p, paddingVal);
        else if (template === 'sleekdark') html = renderSleekDarkTemplate(p, paddingVal);
        else if (template === 'boldmodern') html = renderBoldModernTemplate(p, paddingVal);
        else if (template === 'infographic') html = renderInfographicTemplate(p, paddingVal);
        else if (template === 'minimalgrid') html = renderMinimalGridTemplate(p, paddingVal);
        else if (template === 'coverletter') html = renderCoverLetterTemplate(p, paddingVal);
      }

      container.innerHTML = html;
      generateQRCodeImage();
    }

    function renderStudioCustomTemplate(t, p) {
      let tHTML = t.html || '';
      tHTML = tHTML.replace(/\{\{NAME\}\}/g, escapeXml(p.fullName || 'Your Name'));
      tHTML = tHTML.replace(/\{\{TITLE\}\}/g, escapeXml(p.jobTitle || 'Profession'));
      tHTML = tHTML.replace(/\{\{EMAIL\}\}/g, escapeXml(p.email || ''));
      tHTML = tHTML.replace(/\{\{PHONE\}\}/g, escapeXml(p.phone || ''));
      tHTML = tHTML.replace(/\{\{LOCATION\}\}/g, escapeXml(p.location || ''));
      tHTML = tHTML.replace(/\{\{WEBSITE\}\}/g, escapeXml(p.website || ''));
      tHTML = tHTML.replace(/\{\{PHOTO\}\}/g, p.photo ? `<img src="${escapeAttr(p.photo)}" class="profile-img" alt="Photo"/>` : '');
      tHTML = tHTML.replace(/\{\{SUMMARY\}\}/g, resumeData.summary ? `<p>${escapeXml(resumeData.summary)}</p>` : '');
      tHTML = tHTML.replace(/\{\{EXPERIENCE\}\}/g, renderCommonExperience());
      tHTML = tHTML.replace(/\{\{EDUCATION\}\}/g, renderCommonEducation());
      tHTML = tHTML.replace(/\{\{SKILLS\}\}/g, renderCommonSkills());
      tHTML = tHTML.replace(/\{\{PROJECTS\}\}/g, renderCommonProjects());
      tHTML = tHTML.replace(/\{\{LANGUAGES\}\}/g, renderCommonLanguages());
      tHTML = tHTML.replace(/\{\{CERTIFICATIONS\}\}/g, renderCommonCertifications());
      tHTML = tHTML.replace(/\{\{SOCIALS\}\}/g, renderCommonSocials());
      tHTML = tHTML.replace(/\{\{REFERENCES\}\}/g, renderCommonReferences());
      tHTML = tHTML.replace(/\{\{CUSTOM\}\}/g, renderCommonCustom());
      return tHTML;
    }

        function renderModernTemplate(p, padding) {
      return `
        <div class="template-modern">
          <div class="sidebar">
            ${p.photo ? `<img src="${escapeAttr(p.photo)}" class="profile-img" alt="Profile"/>` : ""}
            <div style="font-size:1.4rem; font-weight:700; text-align:center;">${escapeXml(p.fullName || "Your Name")}</div>
            <div style="font-size:0.85rem; text-align:center; opacity:0.8; margin-bottom:1.5rem;">${escapeXml(p.jobTitle || "Profession")}</div>
            <div style="font-size:0.8rem; margin-bottom:1.25rem;">
              ${p.email ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-envelope"></i> <a href="${escapeAttr(formatMailto(p.email))}" style="color:#fff;">${escapeXml(p.email)}</a></div>` : ""}
              ${p.phone ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-phone"></i> <a href="${escapeAttr(formatTel(p.phone))}" style="color:#fff;">${escapeXml(p.phone)}</a></div>` : ""}
              ${p.location ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-location-dot"></i> ${escapeXml(p.location)}</div>` : ""}
              ${p.website ? `<div style="margin-bottom:0.35rem;"><i class="fa-solid fa-globe"></i> <a href="${escapeAttr(formatURL(p.website))}" target="_blank" style="color:#fff;">${escapeXml(p.website)}</a></div>` : ""}
            </div>

            ${resumeData.skills.length ? `<div style="margin-bottom:1.25rem;"><div style="font-weight:700; text-transform:uppercase; border-bottom:1px solid rgba(255,255,255,0.3); padding-bottom:2px; margin-bottom:0.5rem;">Skills</div>${resumeData.skills.map(s => `<div style="font-size:0.8rem; margin-bottom:0.25rem;">${escapeXml(s.name)} (${s.level}%)</div>`).join("")}</div>` : ""}
